sys_variable_value.value:
(function execute(inputs, outputs) {
  var TABLE_BASE = 'x_1834930_office_0_office_base';
  var TABLE_REG  = 'x_1834930_office_0_base_registration';

  outputs.is_full = false;
  outputs.approved_count = 0;
  outputs.pending_count = 0;
  outputs.capacity = 0;

  try {
    var baseId = (inputs.base_id || '').toString().trim();
    if (!baseId) return;

    var base = new GlideRecord(TABLE_BASE);
    if (!base.get(baseId)) return;

    var cap = parseInt(base.getValue('max_capacity'), 10) || 0;
    outputs.capacity = cap;

    if (cap <= 0) return;

    var ga = new GlideAggregate(TABLE_REG);
    ga.addAggregate('COUNT');
    ga.addQuery('base', baseId);
    ga.addQuery('state', '2');
    ga.query();
    if (ga.next()) outputs.approved_count = parseInt(ga.getAggregate('COUNT'), 10) || 0;

    var gp = new GlideAggregate(TABLE_REG);
    gp.addAggregate('COUNT');
    gp.addQuery('base', baseId);
    gp.addQuery('state', 'IN', '-5,1');
    gp.query();
    if (gp.next()) outputs.pending_count = parseInt(gp.getAggregate('COUNT'), 10) || 0;

    outputs.is_full = (outputs.approved_count === cap) && (outputs.pending_count === 0);

  } catch (e) {
  }
})(inputs, outputs);

